sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var caseId = steps('{{step['5092f9db6013477d9a90b84c6122b2d5'].record_id}}');
    var slaGR = new GlideRecord('task_sla');
    slaGR.addQuery('task', caseId);
    slaGR.query();
    var count = slaGR.getRowCount();
    assertEqual({
        name: 'SLA record exists in Pending state',
        shouldbe: 'true',
        value: String(count > 0)
    });
    // Check if any SLA has pause_time set (indicating pause)
    slaGR.initialize();
    slaGR.addQuery('task', caseId);
    slaGR.addNotNullQuery('pause_time');
    slaGR.query();
    var pausedCount = slaGR.getRowCount();
    stepResult.setOutputMessage('Found ' + count + ' SLA record(s); ' + pausedCount + ' with pause_time set');
})(outputs, steps, params, stepResult, assertEqual);

